[CmdletBinding()]param([string]$PackageRoot)
$ErrorActionPreference='Stop';$PSNativeCommandUseErrorActionPreference=$false;if([string]::IsNullOrWhiteSpace($PackageRoot)){$PackageRoot=Split-Path -Parent $PSScriptRoot};$root=(Resolve-Path -LiteralPath $PackageRoot).Path;$payload=Join-Path $root payload;$pm=Get-Content -Raw -LiteralPath (Join-Path $root manifest.json)|ConvertFrom-Json;$nvcuda=Join-Path $env:WINDIR System32\nvcuda.dll;if(-not(Test-Path -LiteralPath $nvcuda)){throw'NVIDIA driver not found'};$integrity=$true;foreach($p in $pm.base_payload_sha256.psobject.Properties){$integrity=$integrity-and(Get-FileHash -LiteralPath (Join-Path $payload $p.Name)).Hash-eq$p.Value};foreach($p in $pm.variant_payload_sha256.psobject.Properties){$integrity=$integrity-and(Get-FileHash -LiteralPath (Join-Path $payload ("variants\"+$p.Name))).Hash-eq$p.Value};$x=[int]$pm.target_cta[0];$y=[int]$pm.target_cta[1];$stamp=Get-Date -Format yyyyMMdd_HHmmss;$work=Join-Path $root "_n0_cta${x}_${y}_mma176_a_fusion_sweep_work_$stamp";$result=Join-Path $root "_n0_cta${x}_${y}_mma176_a_fusion_sweep_reference_result_$stamp";New-Item -ItemType Directory -Path $work,$result|Out-Null
function Run-Probe($ptx,$tag,[int]$extra){$json=Join-Path $work "$tag.json";$scratch=Join-Path $work "$tag.scratch.raw";$output=Join-Path $work "$tag.output.raw";$log=Join-Path $work "$tag.log";$args=@('--nvcuda',$nvcuda,'--ptx',$ptx,'--function',$pm.function,'--json',$json,'--n0-input',(Join-Path $payload input_rgba16f.raw),'--n0-weights',(Join-Path $payload weights.raw),'--n0-params',(Join-Path $payload params.raw),'--n0-scratch-out',$scratch,'--n0-output',$output,'--n0-grid-x','80','--n0-grid-y','48');if($extra-gt 0){$args+=@('--n0-scratch-extra-bytes',[string]$extra)};& (Join-Path $payload neural_reference_probe.exe) @args *> $log;[ordered]@{exit=$LASTEXITCODE;json=$json;scratch=$scratch;output=$output;log=$log}}
$base=Run-Probe (Join-Path $payload n0_original.ptx) baseline 0;$baseProbe=Get-Content -Raw -LiteralPath $base.json|ConvertFrom-Json;$baseHash=(Get-FileHash -LiteralPath $base.output).Hash;$traceSize=[int]$pm.trace_bytes_per_variant;$combined=[byte[]]::new([int]$pm.variant_count*$traceSize);$rows=@();$allRuns=$base.exit-eq 0-and$baseProbe.pass
foreach($v in $pm.variants){$tag="stage_$('{0:D2}'-f[int]$v.index)";$run=Run-Probe (Join-Path $payload ("variants\"+$v.filename)) $tag ([int]$pm.scratch_extra_bytes);$probe=Get-Content -Raw -LiteralPath $run.json|ConvertFrom-Json;$oh=(Get-FileHash -LiteralPath $run.output).Hash;$s=[IO.File]::OpenRead($run.scratch);try{[void]$s.Seek([int64]$pm.trace_offset,[IO.SeekOrigin]::Begin);$b=[byte[]]::new($traceSize);$read=0;while($read-lt$b.Length){$n=$s.Read($b,$read,$b.Length-$read);if($n-eq 0){break};$read+=$n};if($read-ne$b.Length){throw"short trace $tag $read"};[Array]::Copy($b,0,$combined,[int]$v.index*$traceSize,$traceSize)}finally{$s.Dispose()};$nz=@($b|Where-Object{$_-ne 0}).Count;$rows+=[ordered]@{index=[int]$v.index;name=$v.name;register=$v.register;probe_exit=$run.exit;probe_pass=[bool]$probe.pass;output_sha256=$oh;output_preserved=$oh-eq$baseHash;trace_sha256=(Get-FileHash -InputStream ([IO.MemoryStream]::new($b)) -Algorithm SHA256).Hash;trace_nonzero_bytes=$nz};$allRuns=$allRuns-and$run.exit-eq 0-and$probe.pass-and$nz-gt 0}
$trace=Join-Path $result single_stage_traces.raw;[IO.File]::WriteAllBytes($trace,$combined);$pass=$integrity-and$allRuns;[ordered]@{schema=1;experiment='rtx_n0_selected_cta_mma176_a_fusion_sweep';status=if($pass){'PASS'}else{'FAIL'};classification='RTX_HIDDEN_FUSION_SINGLE_OBSERVATION_SENSITIVITY';payload_integrity=$integrity;device_name=$baseProbe.device_name;baseline_probe_exit=$base.exit;baseline_probe_pass=[bool]$baseProbe.pass;baseline_output_sha256=$baseHash;grid=@(80,48,1);block=@(32,1,1);target_cta=$pm.target_cta;variant_count=[int]$pm.variant_count;trace_bytes_per_variant=$traceSize;checkpoint_bytes=$combined.Length;checkpoint_sha256=(Get-FileHash -LiteralPath $trace).Hash;variants=$rows}|ConvertTo-Json -Depth 10|Set-Content -LiteralPath (Join-Path $result manifest.json) -Encoding utf8;$zip="$result.zip";Compress-Archive -LiteralPath $result -DestinationPath $zip -CompressionLevel Optimal;Get-Content -Raw -LiteralPath (Join-Path $result manifest.json);Write-Host "Result: $zip";exit $(if($pass){0}else{1})
